// gradle.properties is generated by `expo prebuild`, so the memory caps live here and survive every
// prebuild: the Gradle JVM at 2 GB and the Kotlin compile daemon at 1 GB (the build machine is also
// running the emulator and Docker). Existing values are replaced, not duplicated.
const { withGradleProperties } = require('expo/config-plugins');

const CAPS = {
  'org.gradle.jvmargs': '-Xmx2048m -XX:MaxMetaspaceSize=512m',
  'kotlin.daemon.jvmargs': '-Xmx1g',
};

function applyCaps(props) {
  for (const [key, value] of Object.entries(CAPS)) {
    const found = props.find((p) => p.type === 'property' && p.key === key);
    if (found) found.value = value;
    else props.push({ type: 'property', key, value });
  }
  return props;
}

module.exports = function withGradleMemory(config) {
  return withGradleProperties(config, (cfg) => {
    applyCaps(cfg.modResults);
    return cfg;
  });
};
module.exports.applyCaps = applyCaps;
module.exports.CAPS = CAPS;
